$js = @'
const fs=require('fs'),path=require('path');
const roots=['packages/core/docs','docs','.','packages/core'];
const files=[];const skip=['node_modules','.git','.archify','archive'];
function walk(d){for(const e of fs.readdirSync(d,{withFileTypes:true})){if(skip.includes(e.name))continue;const p=path.join(d,e.name);if(e.isDirectory())walk(p);else if(e.name.endsWith('.md'))files.push(p);}}
for(const r of roots){if(fs.existsSync(r))walk(r);}
const uniq=[...new Set(files)];const broken=[];
for(const f of uniq){const t=fs.readFileSync(f,'utf8');for(const m of t.matchAll(/\]\(([^)\s]+\.md)(?:#[^)]*)?\)/g)){const target=m[1];if(/^https?:/.test(target))continue;const abs=path.resolve(path.dirname(f),target);if(fs.existsSync(abs))continue;if(fs.existsSync(abs+'.md'))continue;broken.push(f+' -> '+target);}}
console.log('文档数:',uniq.length);console.log('断链数:',broken.length);console.log(broken.slice(0,25).join('\n'));
'@
Set-Content -Path "$env:TEMP\fg-linkcheck.js" -Value $js -Encoding UTF8
node "$env:TEMP\fg-linkcheck.js"
